package dev.juliainsight.unicode

import dev.juliainsight.lexer.JuliaChars
import java.util.SortedMap
import java.util.TreeMap

/** Julia's REPL LaTeX / emoji tab-completion table (`\alpha` → `α`), generated by scripts/gen_latex_table.jl. */
object LatexSymbols {
    private val table: TreeMap<String, String> = TreeMap()
    private val reverse: HashMap<String, String> = HashMap()
    private val nameChars = BooleanArray(128)
    var maxNameLength: Int = 0
        private set

    init {
        val stream = LatexSymbols::class.java.getResourceAsStream("/unicode/latex_symbols.tsv")
            ?: error("latex_symbols.tsv missing")
        stream.bufferedReader(Charsets.UTF_8).useLines { lines ->
            for (line in lines) {
                if (line.isEmpty() || line.startsWith("#")) continue
                val tab = line.indexOf('\t')
                if (tab <= 0) continue
                val name = line.substring(0, tab)
                val sb = StringBuilder()
                for (hex in line.substring(tab + 1).split(' ')) if (hex.isNotEmpty()) sb.appendCodePoint(hex.toInt(16))
                val value = sb.toString()
                table[name] = value
                for (c in name) if (c.code < 128 && c != '\\') nameChars[c.code] = true
                if (name.length > maxNameLength) maxNameLength = name.length
                val prev = reverse[value]
                if (prev == null || better(name, prev)) reverse[value] = name
            }
        }
    }

    private fun better(candidate: String, current: String): Boolean {
        val ce = candidate.startsWith("\\:")
        val cu = current.startsWith("\\:")
        if (ce != cu) return !ce
        return candidate.length < current.length || (candidate.length == current.length && candidate < current)
    }

    val size: Int get() = table.size

    fun isNameChar(c: Char): Boolean = c.code < 128 && nameChars[c.code]

    /** Exact lookup; [name] includes the leading backslash. */
    operator fun get(name: String): String? = table[name]

    fun isPrefixOfAny(prefix: String): Boolean = table.ceilingKey(prefix)?.startsWith(prefix) == true

    /** True if some other name starts with [name] (so typing more could still change the result). */
    fun hasLongerMatch(name: String): Boolean = table.higherKey(name)?.startsWith(name) == true

    fun withPrefix(prefix: String): SortedMap<String, String> = table.subMap(prefix, prefix + Char.MAX_VALUE)

    /** The LaTeX input sequence for a symbol, e.g. `θ` → `\theta`. */
    fun latexFor(symbol: String): String? = reverse[symbol]

    fun entries(): Set<Map.Entry<String, String>> = table.entries

    /** Longest common prefix of all names starting with [prefix]. */
    fun commonPrefix(prefix: String): String {
        val sub = withPrefix(prefix)
        if (sub.isEmpty()) return prefix
        val first = sub.firstKey()
        val last = sub.lastKey()
        var i = 0
        while (i < first.length && i < last.length && first[i] == last[i]) i++
        return first.substring(0, i)
    }
}

object Subscripts {
    private val SUB: Map<Char, Char> = mapOf(
        '0' to '₀', '1' to '₁', '2' to '₂', '3' to '₃', '4' to '₄', '5' to '₅', '6' to '₆', '7' to '₇', '8' to '₈', '9' to '₉',
        'a' to 'ₐ', 'e' to 'ₑ', 'h' to 'ₕ', 'i' to 'ᵢ', 'j' to 'ⱼ', 'k' to 'ₖ', 'l' to 'ₗ', 'm' to 'ₘ', 'n' to 'ₙ',
        'o' to 'ₒ', 'p' to 'ₚ', 'r' to 'ᵣ', 's' to 'ₛ', 't' to 'ₜ', 'u' to 'ᵤ', 'v' to 'ᵥ', 'x' to 'ₓ',
        'β' to 'ᵦ', 'γ' to 'ᵧ', 'ρ' to 'ᵨ', 'φ' to 'ᵩ', 'χ' to 'ᵪ',
    )
    private val DIGITS: Set<Char> = "₀₁₂₃₄₅₆₇₈₉".toSet()

    fun of(c: Char): Char? = SUB[c]
    fun isSubscriptDigit(c: Char): Boolean = c in DIGITS
    fun isLetterWithSubscript(c: Char): Boolean = c.isLetter() && SUB.containsKey(c)
}

/** Classifies a code point produced by a LaTeX sequence. */
internal object SymbolKind {
    /** Combining marks attach to the previous character (`x\hat` → x̂). */
    fun isCombining(cp: Int): Boolean = when (Character.getType(cp).toByte()) {
        Character.NON_SPACING_MARK, Character.COMBINING_SPACING_MARK, Character.ENCLOSING_MARK -> true
        else -> false
    }

    /** Characters that can only continue an identifier: accents, sub/superscripts, primes. */
    fun isIdentifierContinuation(value: String): Boolean {
        if (value.isEmpty()) return false
        val cp = value.codePointAt(0)
        // sub-/superscript blocks and modifier letters (ᵢ, ʲ, ⁺, ₙ, …)
        if (cp in 0x2070..0x209F || cp in 0x1D2C..0x1DBF || cp in 0x02B0..0x02FF || cp == 0x2C7C || cp == 0xB2 || cp == 0xB3 || cp == 0xB9) return true
        return JuliaChars.isIdChar(cp) && !JuliaChars.isIdStart(cp)
    }
}
